mapper.select:
SELECT s.session_id FROM nw_chat_sessions s JOIN nw_foundation_resource_ownership o ON o.resource_id=s.id AND o.scope_key=#{scope} AND o.kind='session'
WHERE s.tenant_id::text=#{scope} AND (o.owner_member_id=#{memberId}
OR o.department_id::text IN #{id}) ORDER BY s.id

SELECT o.resource_id::text FROM nw_foundation_resource_ownership o WHERE o.scope_key=#{scope} AND o.kind=#{kind}
AND (o.owner_member_id=#{memberId}
  OR o.department_id::text IN #{id}
  OR EXISTS(SELECT 1 FROM nw_foundation_resource_grants g WHERE g.scope_key=o.scope_key AND g.kind=o.kind AND g.resource_id=o.resource_id AND g.action=#{action}
    AND ((g.grantee_type='member' AND g.grantee_id=#{memberId})
      OR (g.grantee_type='department' AND g.grantee_id=#{departmentId} AND EXISTS(SELECT 1 FROM nw_foundation_departments d WHERE d.scope_key=#{scope} AND d.id=g.grantee_id AND d.enabled))
      OR (g.grantee_type='role' AND EXISTS(SELECT 1 FROM nw_foundation_member_roles mr JOIN nw_foundation_roles r ON r.scope_key=mr.scope_key AND r.id=mr.role_id AND r.enabled WHERE mr.scope_key=#{scope} AND mr.member_id=#{memberId} AND mr.role_id=g.grantee_id)))))
ORDER BY o.resource_id

SELECT EXISTS (

    SELECT 1 FROM nw_agents WHERE tenant_id=#{tenantId} AND id=#{resourceId}
    SELECT 1 FROM nw_workflow_containers WHERE tenant_id=#{tenantId} AND id=#{resourceId}
    SELECT 1 FROM nw_knowledge_bases WHERE tenant_id=#{tenantId} AND id=#{resourceId}
    SELECT 1 WHERE false

)
